"use client";

import * as React from "react";
import { Toast as ToastPrimitive } from "@base-ui/react/toast";

import {
  Toast,
  ToastClose,
  ToastDescription,
  ToastProvider,
  ToastTitle,
  ToastViewport,
} from "./toast";
import {
  TOAST_LIMIT,
  syncFromManager,
  toastManager,
  type ToastData,
} from "./use-toast";

/** Renders every live toast from the manager, with its title, detail and action. */
function ToastList() {
  const { toasts } = ToastPrimitive.useToastManager();

  // Copy removals made inside the provider (timeout, swipe, close button)
  // back into the hook's store, so useToast().toasts never keeps stale rows.
  React.useEffect(() => {
    syncFromManager(toasts);
  }, [toasts]);

  return (
    <>
      {toasts
        .filter((toastObject) => !toastObject.limited)
        .map((toastObject) => {
          const { id, title, description, data } = toastObject;
          // SAFETY: `data` is what the toast hook stored on this toast, so it
          // has the ToastData shape written on the way in.
          const { action, rootProps } = (data ?? {}) as Partial<ToastData>;
          return (
            <Toast key={id} toast={toastObject} {...rootProps}>
              <div className="grid gap-1">
                {title && <ToastTitle>{title}</ToastTitle>}
                {description && <ToastDescription>{description}</ToastDescription>}
              </div>
              {action}
              <ToastClose />
            </Toast>
          );
        })}
    </>
  );
}

/** Ink mail Toaster: mount once near the root to show toasts from toast(). */
export function Toaster() {
  return (
    <ToastProvider toastManager={toastManager} limit={TOAST_LIMIT}>
      <ToastViewport>
        <ToastList />
      </ToastViewport>
    </ToastProvider>
  );
}
